/**
 * WorkflowStatus.jsx
 * ------------------
 * Displays a linear progress indicator for the 6-stage debug workflow.
 */

const STAGES = [
  { id: 'idle',       label: 'Code Submitted' },
  { id: 'analyzing', label: 'Analyzing' },
  { id: 'analyzed',  label: 'Root Cause Found' },
  { id: 'fixing',    label: 'Fix Proposed' },
  { id: 'testing',   label: 'Tests Running' },
  { id: 'verified',  label: 'Verified' },
]

// Map app stage names to a numeric index for comparison
const STAGE_INDEX = {
  idle:       0,
  analyzing:  1,
  analyzed:   2,
  fixing:     3,   // fix has been requested / is in progress
  fixed:      3,   // fix result received
  testing:    4,
  verified:   5,
}

export default function WorkflowStatus({ stage }) {
  const currentIndex = STAGE_INDEX[stage] ?? 0

  return (
    <nav className="workflow-status" aria-label="Workflow progress">
      {STAGES.map((s, idx) => {
        let state = 'pending'
        if (idx < currentIndex) state = 'done'
        else if (idx === currentIndex) state = 'active'

        return (
          <div key={s.id} className={`workflow-step workflow-step--${state}`}>
            <div className="workflow-node" aria-hidden="true">
              {state === 'done' ? '✓' : idx + 1}
            </div>
            <span className="workflow-label">{s.label}</span>
            {idx < STAGES.length - 1 && (
              <div className={`workflow-connector workflow-connector--${state === 'done' ? 'done' : 'pending'}`} aria-hidden="true" />
            )}
          </div>
        )
      })}
    </nav>
  )
}

