        // Use stage-specific label override when this step is active
        const label =
          state === 'active' && STAGE_LABEL_OVERRIDE[stage]
            ? STAGE_LABEL_OVERRIDE[stage]
            : s.label

        return (
          <div key={s.id} className={`workflow-step workflow-step--${state}`}>
            <div className="workflow-node" aria-hidden="true">
              {state === 'done' ? '✓' : idx + 1}
            </div>
            <span className="workflow-label">{label}</span>
            {idx < STAGES.length - 1 && (
              <div className={`workflow-connector workflow-connector--${state === 'done' ? 'done' : 'pending'}`} aria-hidden="true" />
            )}
          </div>
        )
      })}
    </nav>
  )
}

